:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-fog-tile: #f3f4f6;
  --color-frosted-glass: #f4f4f4b8;
  --color-sand-backdrop: #e3dccd;
  --color-jet-footer: #111111;
  --color-ink: #242424;
  --color-graphite-body: #374151;
  --color-slate-caption: #5f6570;
  --color-pewter-lede: #6a6e78;
  --color-ash-hint: #858993;
  --color-mist-hairline: #e5e7eb;
  --color-ember-signal: #cc4510;
  --color-moss-confirmed: #15803d;

  /* Typography — Font Families */
  --font-cal-sans: "Cal Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-system-ui: -apple-system, ui-sans-serif, system-ui, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-ui-monospace: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1;
  --tracking-small: 0.66px;
  --text-caption: 12px;
  --leading-caption: 1.33;
  --tracking-caption: 0px;
  --text-body-sm: 13px;
  --leading-body-sm: 1.3;
  --tracking-body-sm: 0px;
  --text-body: 14px;
  --leading-body: 1.35;
  --tracking-body: 0px;
  --text-body-lg: 16px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 17px;
  --leading-subheading: 1.3;
  --tracking-subheading: -0.17px;
  --text-heading-sm: 20px;
  --leading-heading-sm: 1.4;
  --tracking-heading-sm: 0px;
  --text-heading: 40px;
  --leading-heading: 1.1;
  --tracking-heading: -0.4px;
  --text-heading-lg: 56px;
  --leading-heading-lg: 1.05;
  --tracking-heading-lg: -0.56px;
  --text-display: 80px;
  --leading-display: 1.08;
  --tracking-display: -0.8px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-15: 15px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-64: 64px;
  --spacing-96: 96px;
  --spacing-128: 128px;

  /* Layout */
  --layout-max-width: 1320px;
  --layout-section-gap: 128px;
  --layout-card-padding: 24px;
  --layout-element-gap: 8px;

  /* Border Radius */
  --radius-sm-2: 3px;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 10px;
  --radius-lg-2: 12px;
  --radius-xl: 14px;
  --radius-2xl: 18px;
  --radius-2xl-2: 20px;
  --radius-3xl: 22px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-tags: 3px;
  --radius-badges: 4px;
  --radius-inputs: 8px;
  --radius-small-elements: 8px;
  --radius-buttons: 12px;
  --radius-inner-tiles: 14px;
  --radius-images: 14px;
  --radius-nav: 14px;
  --radius-sections: 18px;
  --radius-cards: 20px;
  --radius-small-cards: 22px;
  --radius-pills: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-subtle-2: inset 0 -1px 0 0 #e5e7eb;
  --shadow-sm: inset 0 0 0 1px rgba(15, 35, 75, 0.07);
  --shadow-sm-2: inset 0 0 0 1px #e5e7eb;
  --shadow-md: inset 0 1px 0 0 #ffffff, 0 0 0 1px rgba(15, 35, 75, 0.07), 0 1px 2px 0 rgba(15, 35, 75, 0.04);
  --shadow-md-2: inset 0 1px 0 0 rgba(255, 255, 255, 0.16), 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-tile: #f3f4f6;
  --surface-frosted-glass: #f4f4f4b8;
  --surface-jet-footer: #111111;
}

